import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_DIGITS = "0123456789"
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}


def _norm_email(raw):
    s = raw
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _email_valid(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _norm_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("ext", "x", "#"):
        i = s.find(marker)
        if i != -1:
            cut = min(cut, i)
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _phone_valid(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _norm_zip(raw):
    s = raw.strip()
    m = re.fullmatch(r"([0-9]{5})-[0-9]{4}", s)
    if m:
        s = m.group(1)
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    return s if re.fullmatch(r"[0-9]{5}", s) else ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _norm_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw)} - {""}


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        def get(key):
            return row.get(key) or ""

        email = _norm_email(get("email"))
        if not _email_valid(email):
            email = ""

        digits = _norm_phone(get("phone"))
        phone = digits if _phone_valid(digits) else ""

        if not email and not phone:
            continue

        recs.append({
            "idx": idx,
            "first_name": _norm_name(get("first_name")),
            "last_name": _norm_name(get("last_name")),
            "zip": _norm_zip(get("zip")),
            "email": email,
            "phone": phone,
            "source": get("source").strip().lower(),
            "tags": _norm_tags(get("tags")),
            "opted_out": get("opted_out").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(get("updated")),
        })

    # Step 2: union-find over the kept rows (transitive matching).
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_owner = {}
    phone_owner = {}
    for k, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_owner:
                union(k, email_owner[r["email"]])
            else:
                email_owner[r["email"]] = k

        last = r["last_name"].lower()
        if r["phone"] and last:
            key = (r["phone"], last)
            if key in phone_owner:
                union(k, phone_owner[key])
            else:
                phone_owner[key] = k

    # Group rows; dict insertion order = order of each group's earliest row.
    groups = {}
    for k in range(len(recs)):
        groups.setdefault(find(k), []).append(recs[k])

    # Step 3: pick field values and build one output dict per person.
    def pick(members, field):
        cands = [m for m in members if m[field]]
        if not cands:
            return ""
        best = max(
            cands,
            key=lambda m: (
                m["source"] == "manual",
                m["updated"] is not None,
                m["updated"] if m["updated"] is not None else datetime.min,
                -m["idx"],
            ),
        )
        return best[field]

    out = []
    for members in groups.values():
        dates = [m["updated"] for m in members if m["updated"] is not None]
        tags = set().union(*(m["tags"] for m in members))
        out.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(m["opted_out"] for m in members) else "N",
            "updated": max(dates).strftime("%Y-%m-%d") if dates else "",
        })
    return out
